tinymce.create("tinymce.plugins.yellowbox_button",{init:function(t,e){t.addButton("yellowbox_button",{title:"Add styled button",text:"Insert Button",icon:!1,onclick:function(){t.windowManager.open({title:"Insert Button",body:[{type:"textbox",name:"buttonText",label:"Button Text",value:"Click Here"},{type:"textbox",name:"buttonURL",label:"Button URL",value:"https://"},{type:"listbox",name:"buttonType",label:"Button Type",values:[{text:"Primary",value:"primary"},{text:"Outline Primary",value:"outline-primary"},{text:"Light",value:"light"},{text:"Outline Light",value:"outline-light"},{text:"Dark",value:"dark"},{text:"Outline Dark",value:"outline-dark"}]},{type:"checkbox",name:"openInNewTab",label:"Open In New Tab"}],onsubmit:function(e){var n=e.data.openInNewTab?' target="_blank" rel="noopener"':"";t.insertContent('<a href="'+e.data.buttonURL+'"'+n+' class="btn btn-'+e.data.buttonType+'">'+e.data.buttonText+"</a>")}})}})}}),tinymce.PluginManager.add("yellowbox_button",tinymce.plugins.yellowbox_button),tinymce.PluginManager.add("yellowbox_checklist",(function(t,e){t.addButton("yellowbox_checklist_btn",{text:"Insert Checklist",tooltip:"Insert Checklist",icon:!1,onclick:function(){var e=t.selection.getNode(),n=t.dom.getParent(e,"ul");if(n)t.dom.hasClass(n,"list-checklist")?t.dom.removeClass(n,"list-checklist"):t.dom.addClass(n,"list-checklist");else{t.execCommand("InsertUnorderedList");var l=t.dom.getParent(t.selection.getNode(),"ul");l&&t.dom.addClass(l,"list-checklist")}}})}));